contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint setMin, uint depAmt, uint am, address key) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depAmt)); require(depAmt <= 1000000000000000000000000000000);
        require(key != address(this));
        require(setMin <= depAmt);
        require(am <= depAmt);

        c.SetMinSum(setMin); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.Deposit{value: depAmt}(); if (__ESBMC_reverted()) return;

        uint callerBalBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint keyBalBefore = c.balances(key); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;

        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint callerBalAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint keyBalAfter = c.balances(key); if (__ESBMC_reverted()) return;
        uint cBalAfter = address(c).balance;

        assert(reverted
            || (callerBalAfter == callerBalBefore - am
                && cBalAfter == cBalBefore - am
                && keyBalAfter == keyBalBefore));
    }

    receive() external payable {}
}

