        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 setMin, uint256 depAmt, uint256 am, address key) internal {
        depAmt = bound(depAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(key != address(this));
        vm.assume(setMin <= depAmt);
        vm.assume(am <= depAmt);
        try c.SetMinSum(setMin) {} catch { return; }
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: depAmt}() {} catch { return; }
        uint256 callerBalBefore;
        try c.balances(address(this)) returns (uint256 __r) { callerBalBefore = __r; } catch { return; }
        uint256 keyBalBefore;
        try c.balances(key) returns (uint256 __r) { keyBalBefore = __r; } catch { return; }
        uint cBalBefore = address(c).balance;
        bool reverted;
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
